 namespace Pterodactyl\Services\Dezerx\Staff; use Pterodactyl\Models\Permission; class StaffPresets { public const READ_ONLY = 'read_only'; public const STANDARD = 'standard'; public const FULL = 'full'; public const SCOPES = [self::READ_ONLY, self::STANDARD, self::FULL]; public const LABELS = [ self::READ_ONLY => 'Read only', self::STANDARD => 'Standard support', self::FULL => 'Full access', ]; public const HINTS = [ self::READ_ONLY => 'Can look at everything and change nothing. Console output, files, backups and settings are all readable.', self::STANDARD => 'The usual support set: console and power, files, startup, backups, schedules and databases.', self::FULL => 'Everything this system is allowed to hand out, including SFTP and allocations.', ]; public const NEVER = [ Permission::ACTION_USER_READ, Permission::ACTION_USER_CREATE, Permission::ACTION_USER_UPDATE, Permission::ACTION_USER_DELETE, Permission::ACTION_SETTINGS_REINSTALL, ]; public const DEFAULTS = [ self::READ_ONLY => [ Permission::ACTION_WEBSOCKET_CONNECT, Permission::ACTION_FILE_READ, Permission::ACTION_FILE_READ_CONTENT, Permission::ACTION_BACKUP_READ, Permission::ACTION_DATABASE_READ, Permission::ACTION_SCHEDULE_READ, Permission::ACTION_ALLOCATION_READ, Permission::ACTION_STARTUP_READ, Permission::ACTION_ACTIVITY_READ, ], self::STANDARD => [ Permission::ACTION_WEBSOCKET_CONNECT, Permission::ACTION_CONTROL_CONSOLE, Permission::ACTION_CONTROL_START, Permission::ACTION_CONTROL_STOP, Permission::ACTION_CONTROL_RESTART, Permission::ACTION_FILE_READ, Permission::ACTION_FILE_READ_CONTENT, Permission::ACTION_FILE_CREATE, Permission::ACTION_FILE_UPDATE, Permission::ACTION_FILE_DELETE, Permission::ACTION_FILE_ARCHIVE, Permission::ACTION_BACKUP_READ, Permission::ACTION_BACKUP_CREATE, Permission::ACTION_BACKUP_RESTORE, Permission::ACTION_DATABASE_READ, Permission::ACTION_DATABASE_CREATE, Permission::ACTION_DATABASE_UPDATE, Permission::ACTION_SCHEDULE_READ, Permission::ACTION_SCHEDULE_CREATE, Permission::ACTION_SCHEDULE_UPDATE, Permission::ACTION_SCHEDULE_DELETE, Permission::ACTION_STARTUP_READ, Permission::ACTION_STARTUP_UPDATE, Permission::ACTION_ALLOCATION_READ, Permission::ACTION_ACTIVITY_READ, ], self::FULL => [ Permission::ACTION_WEBSOCKET_CONNECT, Permission::ACTION_CONTROL_CONSOLE, Permission::ACTION_CONTROL_START, Permission::ACTION_CONTROL_STOP, Permission::ACTION_CONTROL_RESTART, Permission::ACTION_FILE_READ, Permission::ACTION_FILE_READ_CONTENT, Permission::ACTION_FILE_CREATE, Permission::ACTION_FILE_UPDATE, Permission::ACTION_FILE_DELETE, Permission::ACTION_FILE_ARCHIVE, Permission::ACTION_FILE_SFTP, Permission::ACTION_BACKUP_READ, Permission::ACTION_BACKUP_CREATE, Permission::ACTION_BACKUP_DELETE, Permission::ACTION_BACKUP_DOWNLOAD, Permission::ACTION_BACKUP_RESTORE, Permission::ACTION_DATABASE_READ, Permission::ACTION_DATABASE_CREATE, Permission::ACTION_DATABASE_UPDATE, Permission::ACTION_DATABASE_DELETE, Permission::ACTION_DATABASE_VIEW_PASSWORD, Permission::ACTION_SCHEDULE_READ, Permission::ACTION_SCHEDULE_CREATE, Permission::ACTION_SCHEDULE_UPDATE, Permission::ACTION_SCHEDULE_DELETE, Permission::ACTION_STARTUP_READ, Permission::ACTION_STARTUP_UPDATE, Permission::ACTION_STARTUP_DOCKER_IMAGE, Permission::ACTION_ALLOCATION_READ, Permission::ACTION_ALLOCATION_CREATE, Permission::ACTION_ALLOCATION_UPDATE, Permission::ACTION_ALLOCATION_DELETE, Permission::ACTION_SETTINGS_RENAME, Permission::ACTION_ACTIVITY_READ, ], ]; public static function scope(?string $value): string { $value = str_replace('-', '_', mb_strtolower(trim((string) $value))); return in_array($value, self::SCOPES, true) ? $value : self::STANDARD; } public static function known(): array { $permissions = []; foreach (Permission::permissions() as $prefix => $group) { foreach (array_keys($group['keys']) as $key) { $permissions[] = $prefix . '.' . $key; } } return $permissions; } public static function grantable(): array { return array_values(array_diff(self::known(), self::NEVER)); } public static function preset(string $scope): array { $scope = self::scope($scope); $stored = Staff::blob()['presets'][$scope] ?? null; $base = is_array($stored) && $stored !== [] ? $stored : self::DEFAULTS[$scope]; return self::clean($base); } public static function presets(): array { $out = []; foreach (self::SCOPES as $scope) { $out[$scope] = self::preset($scope); } return $out; } public static function describe(): array { $out = []; foreach (self::SCOPES as $scope) { $out[] = [ 'key' => $scope, 'label' => self::LABELS[$scope], 'hint' => self::HINTS[$scope], 'permissions' => self::preset($scope), ]; } return $out; } public static function clean(array $permissions): array { $strings = array_filter($permissions, static fn ($value) => is_string($value)); $allowed = array_intersect($strings, self::grantable()); $allowed[] = Permission::ACTION_WEBSOCKET_CONNECT; return array_values(array_unique($allowed)); } public static function resolve(string $scope, array $requested, array $ownerPermissions): array { $preset = self::preset($scope); $wanted = $requested === [] ? $preset : array_intersect(self::clean($requested), $preset); if (!in_array('*', $ownerPermissions, true)) { $wanted = array_intersect($wanted, $ownerPermissions); } $wanted = array_values(array_unique($wanted)); if ($wanted === [] || $wanted === [Permission::ACTION_WEBSOCKET_CONNECT]) { return [Permission::ACTION_WEBSOCKET_CONNECT]; } sort($wanted); return $wanted; } public static function storePresets(array $values): void { $presets = []; foreach (self::SCOPES as $scope) { $given = $values[$scope] ?? null; $presets[$scope] = is_array($given) ? self::clean($given) : self::DEFAULTS[$scope]; } Staff::write(['presets' => $presets]); } } 